svg.script:
//
function selectStructure(id) {
  const root = document.getElementById('piso-08-root');

  // Resetar classes ativas no SVG
  root.classList.remove('active-cortex', 'active-ventriculos', 'active-hipocampo');

  // Ativar classe correta baseada no hotspot
  if (id === 'hs-cortex') {
    root.classList.add('active-cortex');
  } else if (id === 'hs-ventriculos') {
    root.classList.add('active-ventriculos');
  } else if (id === 'hs-hipocampo') {
    root.classList.add('active-hipocampo');
  }

  // Alternar visibilidade dos grupos de painéis com opacidade e pointer-events
  const targets = ['initial', 'hipocampo', 'ventriculos', 'cortex'];
  targets.forEach(target => {
    const panelId = 'panel-' + target;
    const panel = document.getElementById(panelId);
    if (panel) {
      if (id === 'hs-' + target) {
        panel.style.opacity = '1';
        panel.style.pointerEvents = 'auto';
      } else if (id === '' && target === 'initial') {
        panel.style.opacity = '1';
        panel.style.pointerEvents = 'auto';
      } else {
        panel.style.opacity = '0';
        panel.style.pointerEvents = 'none';
      }
    }
  });

  // Atualizar aparência visual dos botões/rótulos
  const buttons = document.querySelectorAll('.hotspot-btn');
  buttons.forEach(btn => {
    const btnHotspot = btn.getAttribute('data-hotspot');
    const rect = btn.querySelector('rect');
    if (btnHotspot === id) {
      rect.style.fill = 'var(--panel-border)';
      rect.style.stroke = 'var(--text-primary)';
      rect.style.strokeWidth = '2px';
    } else {
      rect.style.fill = 'var(--panel-bg)';
      rect.style.stroke = 'var(--panel-border)';
      rect.style.strokeWidth = '1.5px';
    }
  });
}

// Configurar ouvintes usando delegação de eventos na raiz do SVG
const svgRoot = document.getElementById('piso-08-root');

svgRoot.addEventListener('click', (e) => {
  const hotspotEl = e.target.closest('[data-hotspot]');
  if (hotspotEl) {
    selectStructure(hotspotEl.getAttribute('data-hotspot'));
  } else {
    // Clicar fora zera para o estado inicial
    const interactivePart = e.target.closest('.brain-part, .hotspot-btn, rect');
    if (!interactivePart) {
      selectStructure('');
    }
  }
});

svgRoot.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' || e.key === ' ') {
    const hotspotEl = e.target.closest('[data-hotspot]');
    if (hotspotEl) {
      e.preventDefault();
      selectStructure(hotspotEl.getAttribute('data-hotspot'));
    }
  }
});
//
